<script setup>
import {computed,ref,watch} from 'vue';
import {ARROWS,NUMBER_ROWS,arrowShapes,MARKS,availableMarks,MARK_DESCRIPTIONS,KEYCAP_PREVIEWS,DEFAULT_COLORS,defaultDesign,designError,generatePreview} from '../keycaps';
import {colorHex,catalogColorId} from '../keycap-palette.js';
import KeycapPreview from './KeycapPreview.vue';
import PaletteColorPicker from './PaletteColorPicker.vue';
const props=defineProps({profile:Object,profiles:Array,products:Array});
const emit=defineEmits(['change','save']);
const selection=ref(null),paintMode=ref(false),selectedIds=ref([]);
watch(()=>props.profile,p=>{selection.value=p?defaultDesign(p):null;selectedIds.value=[];},{immediate:true});
watch(selection,d=>emit('change',d?structuredClone(JSON.parse(JSON.stringify(d))):null),{deep:true,immediate:true});
const error=computed(()=>designError(selection.value,props.profile));
const design=computed(()=>error.value?null:generatePreview(props.profile,selection.value));
const template=computed(()=>KEYCAP_PREVIEWS[props.profile?.templateId]);
const arrowKey=computed(()=>template.value?.keys.find(k=>k.id==='up' && k.boldArrows) || template.value?.keys.find(k=>k.boldArrows));
const colorFields=[['alpha','Main keys'],['modifiers','Modifiers'],['accents','Accent keys']];
const presets=[{name:'V6 palette',...DEFAULT_COLORS},{name:'Night flight',alpha:'#DCE4ED',modifiers:'#242A36',accents:'#C32D28'},{name:'Terminal',alpha:'#CFDBCD',modifiers:'#303E36',accents:'#83B697'},{name:'Signal',alpha:'#F5EEDB',modifiers:'#454251',accents:'#E6B24C'}].map(p=>({...p,...Object.fromEntries(colorFields.map(([k])=>[k,catalogColorId(p[k])]))}));
const siblings=computed(()=>props.products?.filter(p=>p.active&&p.keycaps&&p.keycaps.profileId!==props.profile?.id)||[]);
const selectedKeys=computed(()=>template.value?.keys.filter(k=>selectedIds.value.includes(k.id)) || []);
const overrideCount=computed(()=>Object.keys(selection.value?.keyColors || {}).length);
const currentKeyColor=key=>selection.value.keyColors[key.id] || selection.value[key.group];
const selectedColor=computed({get:()=>selectedKeys.value.length?currentKeyColor(selectedKeys.value[0]):DEFAULT_COLORS.alpha,set:color=>{
  const overrides={...selection.value.keyColors};
  for(const key of selectedKeys.value){if(color===selection.value[key.group])delete overrides[key.id];else overrides[key.id]=color;}
  selection.value.keyColors=overrides;
}});
const mixedColors=computed(()=>new Set(selectedKeys.value.map(currentKeyColor)).size>1);
function selectKey(id){selectedIds.value=selectedIds.value.includes(id)?selectedIds.value.filter(k=>k!==id):[...selectedIds.value,id];}
function resetSelected(){const overrides={...selection.value.keyColors};for(const id of selectedIds.value)delete overrides[id];selection.value.keyColors=overrides;}
function resetDesign(){selection.value=defaultDesign(props.profile);selectedIds.value=[];}
function preset(p){for(const [k] of colorFields)selection.value[k]=p[k];}
</script>
<template>
  <section class="keycap-studio" aria-labelledby="keycap-studio-title">
    <div class="studio-heading"><div><p class="eyebrow">YOUR KEYBOARD. YOUR SIGNAL.</p><h2 id="keycap-studio-title">MAKE IT YOURS<span>.</span></h2></div><span class="studio-badge">{{profile?.name || 'Keyboard profile unavailable'}}</span></div>
    <p v-if="!template" class="notice">This keyboard profile needs a design template. Please check back soon.</p>
    <template v-else>
      <p class="studio-intro">{{profile.description}}</p>
      <div class="studio-grid">
        <div class="studio-controls">
          <fieldset><legend>01 / Set the palette</legend><div class="preset-list"><button v-for="p in presets" :key="p.name" type="button" @click="preset(p)"><span class="preset-swatches"><i :style="{background:colorHex(p.alpha)}" /><i :style="{background:colorHex(p.modifiers)}" /><i :style="{background:colorHex(p.accents)}" /></span>{{p.name}}</button></div>
            <PaletteColorPicker v-for="[id,label] in colorFields" :key="id" v-model="selection[id]" :label="label" /><p class="palette-note">All choices use the available color selection. Group changes keep your individual key colors.</p>
          </fieldset>
          <fieldset><legend>02 / Choose your Commander key</legend><div class="symbol-list"><button v-for="id in availableMarks(profile)" :key="id" :aria-pressed="selection.mark===id" @click="selection.mark=id"><svg viewBox="0 0 1250 1000" aria-hidden="true"><rect width="1250" height="1000" rx="90" :fill="colorHex(selection.accents)" /><path v-for="l in template.marks[id]" :key="l.path" :d="l.path" :fill="l.fill" /></svg><span>{{MARKS[id]}}</span><small v-if="MARK_DESCRIPTIONS[id]">{{MARK_DESCRIPTIONS[id]}}</small></button></div></fieldset>
          <fieldset><legend>03 / Pick your arrows</legend><div class="arrow-list"><button v-for="id in profile.arrows || Object.keys(ARROWS)" :key="id" :aria-pressed="selection.arrows===id" @click="selection.arrows=id"><svg v-if="arrowKey" viewBox="0 0 1000 1000" aria-hidden="true"><rect width="1000" height="1000" rx="100" :fill="colorHex(selection.keyColors[arrowKey.id] || selection[arrowKey.group])" /><path v-for="shape in arrowShapes(arrowKey,id)" :key="shape.path" :d="shape.path" :fill="shape.fill" /></svg>{{ARROWS[id]}}</button></div></fieldset>
          <fieldset><legend>04 / Number-row legends</legend><div class="number-row-list"><button v-for="id in profile.numberRows || Object.keys(NUMBER_ROWS)" :key="id" type="button" :aria-pressed="selection.numberRow===id" @click="selection.numberRow=id"><span>{{NUMBER_ROWS[id]}}</span><small>{{id==='text'?'Short color labels beneath 1–8':'Sixteen classic color swatches'}}</small></button></div></fieldset>
          <div class="studio-actions"><button class="button primary" :disabled="!!error" @click="$emit('save')">Save design to cart +</button><button class="text-button" @click="resetDesign">Reset to profile defaults</button></div>
          <p v-if="error" role="alert" class="notice">{{error}}</p>
        </div>
        <div class="studio-proof"><div class="paint-toolbar"><button type="button" class="paint-toggle" :aria-pressed="paintMode" @click="paintMode=!paintMode">{{paintMode?'Done selecting keys':'Color individual keys'}} <span aria-hidden="true">{{paintMode?'✓':'+'}}</span></button><span v-if="overrideCount" class="custom-count">{{overrideCount}} custom {{overrideCount===1?'key':'keys'}}</span></div>
          <p v-if="paintMode" class="paint-instructions">Click or tap keys to select them, then choose their color. Click a selected key again to deselect it.</p>
          <div class="preview-scroll"><KeycapPreview v-if="design" :design="design" :interactive="paintMode" :selected-keys="paintMode?selectedIds:[]" @select-key="selectKey" /></div>
          <div v-if="paintMode" class="key-paint-panel"><div class="selection-heading"><strong role="status">{{selectedIds.length}} {{selectedIds.length===1?'key':'keys'}} selected</strong><div><button type="button" @click="selectedIds=template.keys.map(k=>k.id)">Select all</button><button type="button" :disabled="!selectedIds.length" @click="selectedIds=[]">Clear selection</button></div></div>
            <template v-if="selectedKeys.length"><p class="selected-names">{{selectedKeys.map(k=>k.name).join(', ')}}</p><p v-if="mixedColors" class="palette-note">These keys have different colors. Choose a color to apply to all selected keys.</p><PaletteColorPicker v-model="selectedColor" label="Color selected keys" /><button type="button" class="reset-key-colors" @click="resetSelected">Use group colors for selected keys</button></template><p v-else class="palette-note">Select a key in the keyboard above to give it its own color.</p>
          </div><button v-if="overrideCount" type="button" class="reset-key-colors" @click="selection.keyColors={}">Reset all individual key colors</button><p class="proof-caption">LIVE DESIGN PREVIEW · {{template.keys.length}} KEYS · {{template.profileName.toUpperCase()}} PROFILE</p><p>{{template.compatibility}}</p><p class="proof-note">Colors come from the available palette and are shown as a screen preview. Lettering adjusts for light and dark keys. Color-name labels adjust with the lettering; colored boxes, PETSCII graphics and your arrow style retain their palette colors. Check the final manufacturing proof before production.</p><p class="proof-note">Black arrows show best on light keys; white arrows show best on dark keys.</p><p class="studio-process">Choose a design → pay when ordering opens → RODDY reviews and submits your set to the maker. Keyboard sold separately.</p></div>
      </div>
      <nav v-if="siblings.length" class="profile-links" aria-label="Other keyboard sets"><strong>Explore other keyboard profiles</strong><RouterLink v-for="p in siblings" :key="p.id" :to="'/product/'+p.id">{{p.name}} ↗</RouterLink></nav>
    </template>
  </section>
</template>
<style scoped>
.paint-toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:14px}.paint-toggle{display:flex;align-items:center;gap:20px;border:1px solid #93B0DB;padding:10px 14px;font-size:12px}.paint-toggle[aria-pressed=true]{background:#93B0DB22}.custom-count{font:11px monospace;color:#93B0DB}.studio-proof .paint-instructions{font-size:12px;margin:0 0 14px}.key-paint-panel{border:1px solid var(--color-border,#444);padding:16px;margin-top:16px;border-radius:8px}.selection-heading{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;font-size:12px}.selection-heading>div{display:flex;gap:12px}.selection-heading button,.reset-key-colors{font-size:11px;text-decoration:underline}.selection-heading button:disabled{opacity:.4;cursor:default}.studio-proof .selected-names{font-size:11px;max-height:52px;overflow-y:auto;margin:10px 0}.reset-key-colors{margin-top:14px}.studio-controls .palette-note,.studio-proof .palette-note{font-size:11px;line-height:1.6;opacity:.7;margin-top:12px}.keycap-studio{margin:4rem 0;padding:clamp(20px,4vw,48px);border:1px solid var(--color-border,#444);background:var(--color-panel,#101115);border-top:4px solid #7FAFD3}.studio-heading{display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap}.studio-heading h2{font-size:clamp(32px,5vw,64px);font-weight:900;line-height:1.1;margin:12px 0}.studio-heading h2 span{color:#C32D28}.studio-badge{border:1px solid var(--color-border,#444);padding:10px 14px;font:12px monospace}.studio-intro{max-width:760px;margin:12px 0 28px;color:var(--color-text-dim)}.studio-grid{display:grid;grid-template-columns:minmax(250px,340px) minmax(0,1fr);gap:32px}.studio-controls fieldset{margin-bottom:28px}.studio-controls legend{font:12px monospace;font-weight:bold;margin-bottom:14px;text-transform:uppercase}.preset-list{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:18px}.preset-list button{border:1px solid var(--color-border,#444);padding:9px;font-size:11px}.preset-swatches{display:flex;margin-bottom:5px}.preset-swatches i{width:18px;height:14px}.color-choice{display:flex;justify-content:space-between;align-items:center;padding:9px 0;border-bottom:1px solid var(--color-border,#444);font-size:13px}.color-choice small{display:block;font:10px monospace;opacity:.65;margin-top:4px}.color-choice input{width:60px;height:38px;cursor:pointer;border:0;background:none}.symbol-list{display:grid;grid-template-columns:1fr 1fr;gap:8px}.symbol-list button{display:grid;justify-items:center;gap:7px;border:1px solid var(--color-border,#444);padding:9px;font-size:11px}.symbol-list small{font-size:9px;line-height:1.35;opacity:.7}.symbol-list svg{width:65px;height:52px}.symbol-list button[aria-pressed=true],.arrow-list button[aria-pressed=true]{border-color:#7FAFD3;box-shadow:inset 0 0 0 1px #7FAFD3;background:#7FAFD311}.number-row-list{display:grid;gap:8px}.number-row-list button{display:grid;text-align:left;gap:5px;padding:12px;border:1px solid var(--color-border,#444);font-size:12px}.number-row-list button[aria-pressed=true]{border-color:#93B0DB;box-shadow:inset 0 0 0 1px #93B0DB;background:#93B0DB11}.number-row-list small{font-size:10px;opacity:.7}.arrow-list{display:grid;gap:8px}.arrow-list button{display:flex;align-items:center;gap:14px;padding:8px 12px;border:1px solid var(--color-border,#444);font-size:12px}.arrow-list svg{width:42px;height:42px;flex-shrink:0}.studio-actions{display:grid;gap:16px;justify-items:start}.studio-proof{min-width:0;align-self:start;position:sticky;top:90px}.preview-scroll{overflow-x:auto;border-radius:8px;padding-bottom:10px}.proof-caption{font:10px monospace;letter-spacing:1px;margin:18px 0}.studio-proof p{font-size:13px;line-height:1.7}.studio-proof .proof-note{font-size:11px;opacity:.65;margin:14px 0}.studio-process{border-top:1px solid var(--color-border,#444);padding-top:20px;margin-top:20px}.profile-links{display:flex;gap:20px;flex-wrap:wrap;border-top:1px solid var(--color-border,#444);margin-top:30px;padding-top:20px;font-size:12px}@media(max-width:900px){.studio-grid{grid-template-columns:1fr}.studio-proof{position:static;grid-row:1}.studio-controls{display:grid;grid-template-columns:1fr 1fr;gap:20px}.studio-actions{grid-column:1/-1}}@media(max-width:540px){.studio-controls{display:block}.keycap-studio{padding:18px;margin:2rem 0}.studio-proof p{font-size:12px}}
</style>
